'use strict';
// Leaflet provides real Web Mercator geography, geographic layers, zoom,
// pan, scale, and asset interaction. No screenshot or SVG basemap is used.
const campusMapMarkers=new Map();
let egyptMap=null,egyptLayers=null,egyptRoadData=null,egyptPlaceData=null;
let egyptMapView=null,egyptReturnFocus=null,egyptTileLayer=null;
let egyptRenderedScope=null;
let egyptMapMode=navigator.onLine===false?'offline':'streets';
const EGYPT_BOUNDS=[[21.994873,24.703223],[31.65498,36.871387]];
const EGYPT_MAX_BOUNDS=[[21.55,24.25],[32.05,37.25]];
function egyptCountryBounds(){const egypt=(typeof mapFeatures!=='undefined'&&mapFeatures||[]).find(f=>f.properties&&(f.properties.ADM0_A3==='EGY'||f.properties.ADMIN==='Egypt'));if(egypt&&typeof L!=='undefined'){const bounds=L.geoJSON(egypt).getBounds();if(bounds.isValid())return bounds}return L.latLngBounds(EGYPT_BOUNDS)}
let egyptFitToken=0;
function egyptOuterRings(){const egypt=(typeof mapFeatures!=='undefined'&&mapFeatures||[]).find(f=>f.properties&&(f.properties.ADM0_A3==='EGY'||f.properties.ADMIN==='Egypt'));if(!egypt)return [];const coords=egypt.geometry.coordinates;const polygons=egypt.geometry.type==='Polygon'?[coords]:coords;return polygons.map(poly=>poly[0].map(([lon,lat])=>[lat,lon]))}
function addEgyptMask(){if(!egyptMap)return;if(egyptMap._egyptMask){egyptMap.removeLayer(egyptMap._egyptMask);egyptMap._egyptMask=null}const holes=egyptOuterRings();if(!holes.length)return;if(!egyptMap.getPane('egyptMask')){const pane=egyptMap.createPane('egyptMask');pane.style.zIndex=350;pane.style.pointerEvents='none'}const outer=[[-40,-30],[-40,75],[55,75],[55,-30]];egyptMap._egyptMask=L.polygon([outer,...holes],{pane:'egyptMask',stroke:true,color:'#8aa0ae',weight:1.5,fillColor:'#d5e3ea',fillOpacity:1,interactive:false}).addTo(egyptMap)}
function fitEgyptMap(animate){const map=egyptMap;if(!map)return;const size=map.getSize();if(size.x<40||size.y<40){requestAnimationFrame(()=>{if(egyptMap===map)fitEgyptMap(animate)});return}const bounds=egyptCountryBounds();map.setMinZoom(5);const fitted=map._getBoundsCenterZoom(bounds,{padding:[10,10]});const zoom=Math.max(5,Math.min(map.getMaxZoom(),fitted.zoom));const snap=map.options.zoomSnap;map.options.zoomSnap=0;map.setMinZoom(zoom);map.setView(fitted.center,zoom,{animate:!!animate});map.options.zoomSnap=snap;egyptMapView={center:[fitted.center.lat,fitted.center.lng],zoom};addEgyptMask()}
function scheduleEgyptFit(animate){const map=egyptMap;const token=++egyptFitToken;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(token!==egyptFitToken||egyptMap!==map||state.page!=='overview')return;fitEgyptMap(animate)}))}
const EGYPT_COLORS={critical:'#ed686e',warning:'#e4aa47',operational:'#4d8bd6'};
function atlasEgyptCards(){return [...new Set(sites.map(s=>s.region))].filter(name=>state.region==='all'||state.region===name).map(name=>{const ss=sites.filter(s=>s.region===name);return {name,count:ss.reduce((a,s)=>a+s.buildings,0),campuses:ss.length,customers:ss.reduce((a,s)=>a+s.customers,0),best:Math.min(...ss.map(s=>s.pue)),worst:Math.max(...ss.map(s=>s.pue)),renewable:32,status:ss.some(s=>s.status==='critical')?'critical':ss.some(s=>s.status==='warning')?'warning':'operational'}})}
function egyptRegionCard(r){return `<article class="atlas-region-card"><div class="atlas-card-heading"><h2>${r.name}</h2><span class="atlas-bell ${r.status}" title="${r.status}">&#9679;</span></div><div class="atlas-card-content"><div class="atlas-counts"><strong>${r.count}</strong><small>Data center<br>buildings</small><strong>${r.campuses}</strong><small>Campus${r.campuses===1?'':'es'}</small></div><div class="atlas-bars">${[['Best PUE',r.best,2.5,'#91aefa'],['Worst PUE',r.worst,2.5,r.status==='critical'?'#ff7b7e':'#98ace9'],['Renewable utilization',r.renewable,100,'#8ddbc6']].map(([name,value,max,color])=>`<div class="atlas-bar-label"><span>${name}</span><b>${value}${max===100?' %':''}</b></div><div class="atlas-bar-track"><div style="width:${value/max*100}%;background:${color}"></div></div>`).join('')}</div></div></article>`}
overview=function(){let cards=atlasEgyptCards();return `<section class="atlas-map-stage egypt-map-stage" aria-label="Egypt data center map"><div class="egypt-map-area"><div id="egypt-map" class="egypt-leaflet-map" role="region" aria-label="Interactive map of Egypt. Use plus and minus to zoom, arrow keys to pan, and the left navigation to select a campus."></div><div class="egypt-map-title"><span class="egypt-title-flag">EG</span><div><strong class="schneider-map-brand"><img src="assets/schneider-electric.png" alt="Schneider Electric"><span>Unified Operations Center</span></strong><small>${scopedSites().length} campuses · ${state.region==='all'?'National portfolio':esc(state.region)}</small></div></div><div class="egypt-map-options" role="group" aria-label="Map basemap"><button data-map-mode="streets" class="${egyptMapMode==='streets'?'active':''}">Street map</button><button data-egypt-action="fit" aria-label="Fit the map to Egypt">Fit Egypt</button></div><span id="egypt-map-status" class="egypt-map-status">${egyptMapMode==='streets'?'Street map · Internet required':'Offline geographic map'}</span><span class="egypt-demo-tag">SIMULATED FACILITY DATA</span></div><div class="atlas-kpi-strip" style="--card-count:${cards.length}">${cards.map(egyptRegionCard).join('')}</div><div class="atlas-bottom-handle" aria-hidden="true"></div></section>`};
function clearEgyptMap(){if(egyptMap){if(egyptMap._loaded)egyptMapView={center:egyptMap.getCenter(),zoom:egyptMap.getZoom()};egyptMap.remove();egyptMap=null;egyptLayers=null;egyptTileLayer=null}}
function setMapStatus(text){const target=$('#egypt-map-status');if(target)target.textContent=text}
function geoJsonLayer(data,options){return data?.features?.length?L.geoJSON(data,{...options,pane:'offlineBasemap'}):null}
function addOfflineBasemap(){const countries=mapFeatures?{type:'FeatureCollection',features:mapFeatures}:null;const land=geoJsonLayer(countries,{style:f=>({color:'#a1ada0',weight:1,fillColor:f.properties.ADM0_A3==='EGY'?'#f0e9d6':'#e3e5d2',fillOpacity:1}),interactive:false});land?.addTo(egyptLayers);const regions=geoJsonLayer({type:'FeatureCollection',features:governorateFeatures},{style:{color:'#adb6a0',weight:.7,fillColor:'#eeead7',fillOpacity:.24},interactive:false});regions?.addTo(egyptLayers);const rivers=geoJsonLayer({type:'FeatureCollection',features:riverFeatures},{style:{color:'#76afd2',weight:2.4,opacity:.9},interactive:false});rivers?.addTo(egyptLayers);const roads=geoJsonLayer(egyptRoadData,{style:{color:'#c9a571',weight:1.6,opacity:.8},interactive:false});roads?.addTo(egyptLayers);
 const places=egyptPlaceData?.features?.map(f=>({name:f.properties.NAME||f.properties.name,lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0],rank:f.properties.SCALERANK??f.properties.scalerank??5}))||[{name:'Cairo',lat:30.04,lon:31.24,rank:1},{name:'Alexandria',lat:31.2,lon:29.92,rank:1},{name:'Luxor',lat:25.7,lon:32.64,rank:2},{name:'Aswan',lat:24.09,lon:32.9,rank:2},{name:'Suez',lat:29.97,lon:32.55,rank:2},{name:'Mansoura',lat:31.04,lon:31.38,rank:2},{name:'New Administrative Capital',lat:30.02,lon:31.75,rank:3}];
 for(const place of places.filter(p=>p.rank<=3)){L.marker([place.lat,place.lon],{interactive:false,pane:'offlineBasemap',icon:L.divIcon({className:'egypt-place-label',html:`<i></i><span>${esc(place.name)}</span>`,iconSize:null})}).addTo(egyptLayers)}
}
function mountEgyptMap(){if(state.page!=='overview'||typeof L==='undefined'||!$('#egypt-map'))return;egyptMap=L.map('egypt-map',{zoomControl:false,minZoom:5,maxZoom:18,zoomSnap:1,zoomDelta:1,wheelDebounceTime:20,wheelPxPerZoomLevel:60,attributionControl:true,preferCanvas:true,worldCopyJump:false});const restoreEgyptView=egyptMapView;egyptMap.setView(restoreEgyptView?.center||[26.82,30.79],restoreEgyptView?.zoom||6);L.control.zoom({position:'bottomright'}).addTo(egyptMap);L.control.scale({position:'bottomleft',imperial:false}).addTo(egyptMap);egyptMap.attributionControl.addAttribution('<a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a>');egyptMap.createPane('offlineBasemap').style.zIndex=150;egyptLayers=L.layerGroup().addTo(egyptMap);if(egyptMapMode==='offline')addOfflineBasemap();else addStreetTiles();addCampusMarkers();egyptMap.on('moveend',()=>{egyptMapView={center:egyptMap.getCenter(),zoom:egyptMap.getZoom()}});egyptMap.invalidateSize();addEgyptMask();if(!restoreEgyptView&&state.region==='all')scheduleEgyptFit(false)}
function addStreetTiles(){if(!egyptMap)return;let loaded=0,errors=0;egyptTileLayer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,noWrap:true,updateWhenZooming:false,updateWhenIdle:true,keepBuffer:2,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'});egyptTileLayer.on('tileload',()=>{loaded++;setMapStatus('OpenStreetMap · Street map')});egyptTileLayer.on('tileerror',()=>{errors++;if(errors>=3&&loaded===0&&egyptTileLayer&&egyptMap){egyptMap.removeLayer(egyptTileLayer);egyptTileLayer=null;egyptMapMode='offline';addOfflineBasemap();setMapStatus('Offline map · Street tiles unavailable');$('#egypt-map-options');document.querySelectorAll('[data-map-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mapMode==='offline'))}});egyptTileLayer.addTo(egyptMap)}
function addCampusMarkers(){campusMapMarkers.clear();for(const s of sites){let marker=L.circleMarker([s.lat,s.lon],{radius:s.status==='critical'?14:12,color:state.site===s.id?'#44e3c1':'#fff',weight:state.site===s.id?4:2.5,fillColor:'#000000',fillOpacity:1,bubblingMouseEvents:false}).addTo(egyptMap);marker.bindTooltip(esc(s.name),{direction:'top',offset:[0,-16],className:'egypt-campus-tooltip'});marker.bindPopup(`<div class="egypt-campus-popup"><span class="chip ${s.status==='critical'?'red':s.status==='warning'?'amber':'green'}">${s.status}</span><h3>${esc(s.name)}</h3><p>${esc(s.city)} · ${esc(s.region)}</p><dl><div><dt>Buildings</dt><dd>${s.buildings}</dd></div><div><dt>PUE</dt><dd>${s.pue.toFixed(2)}</dd></div><div><dt>Facility power</dt><dd>${s.power} MW</dd></div></dl><p class="popup-nav-hint">Use the left navigation panel to open campus systems.</p></div>`);campusMapMarkers.set(s.id,marker);marker.on('click',()=>selectMapCampus(s.id));marker.on('mouseover',()=>marker.setRadius(16));marker.on('mouseout',()=>marker.setRadius(s.status==='critical'?14:12))}}
const egyptOriginalRender=render;
render=function(){
 const signature=JSON.stringify([state.region,state.site,egyptMapMode]);
 const retain=state.page==='overview'&&egyptMapMode==='streets'&&egyptMap&&egyptRenderedScope===signature&&egyptMapView!==null;
 const container=retain?egyptMap.getContainer():null;
 if(container)container.remove();else clearEgyptMap();
 egyptOriginalRender();
 document.body.classList.toggle('atlas-overview',state.page==='overview');
 document.body.classList.toggle('atlas-detail',state.page!=='overview');
 if(state.page==='overview')$('#breadcrumbs').innerHTML='<span class="atlas-crumb">Unified Operations Center</span><span class="atlas-crumb">'+(state.region==='all'?'National portfolio':esc(state.region))+'</span>';
 buildAtlasNavigation();
 if(container){$('#egypt-map').replaceWith(container);egyptMap.invalidateSize({pan:false});addEgyptMask()}else{mountEgyptMap();egyptRenderedScope=signature}
};
function buildAtlasNavigation(){
 const groups=[...new Set(sites.map(s=>s.region))];
 const available=sites.filter(s=>state.region==='all'||s.region===state.region);
 const selected=sites.find(s=>s.id===state.site);
 $('#atlas-navigation').innerHTML=`<div class="atlas-nav-header"><div><strong>Unified Operations Center</strong><small>Select region, campus, and building</small></div><button id="atlas-close-navigation" aria-label="Close navigation">&#10005;</button></div><div class="atlas-nav-content"><div class="navigation-dropdowns"><label for="nav-region">EGYPT REGION</label><select id="nav-region"><option value="all" ${state.region==='all'?'selected':''}>All Egypt (${sites.length} campuses)</option>${groups.map(region=>`<option value="${esc(region)}" ${state.region===region?'selected':''}>${esc(region)} (${sites.filter(s=>s.region===region).length})</option>`).join('')}</select><label for="nav-campus">CAMPUS</label><select id="nav-campus"><option value="">Select a campus</option>${available.map(s=>`<option value="${s.id}" ${state.site===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><label for="nav-building">BUILDING</label><select id="nav-building" ${selected?'':'disabled'}><option value="">${selected?'Select a building':'Choose a campus first'}</option>${selected?Array.from({length:selected.buildings},(_,i)=>`<option value="DC-0${i+1}" ${state.building===`DC-0${i+1}`?'selected':''}>DC-0${i+1}</option>`).join(''):''}</select>${selected?`<div class="nav-campus-actions"><button class="atlas-tree-button" data-campus="${selected.id}">Campus overview &#8250;</button><button class="atlas-tree-button" data-egypt-focus="${selected.id}">Locate on Egypt map &#8250;</button></div>`:''}</div><div class="atlas-nav-label">OPERATIONS</div><div class="operations-dropdown"><label class="screen-reader" for="nav-operation">Choose operation</label><select id="nav-operation" aria-label="Operations"><option value="" ${!['regions','facilities','alerts','work','insights','logs'].includes(state.page)?'selected':''}>Select an operation</option>${[['regions',state.building?'Building KPIs':state.site?'Campus performance':'Regional performance'],['facilities','Facility directory'],['alerts','Alarm center'],['work','Work orders'],['insights','Predictive insights'],['logs','Team journal']].map(([p,label])=>`<option value="${p}" ${state.page===p?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="atlas-nav-label">${state.building||'DC-01'} / BUILDING SYSTEMS</div>${Object.entries(tabNames).map(([tab,label])=>`<button class="atlas-tree-button ${state.page==='building'&&state.tab===tab?'selected':''}" data-tab="${tab}">${icon(tab)}${label}</button>`).join('')}<div class="atlas-nav-label">TOOLS</div><button class="atlas-tree-button" data-egypt-tool="export">Export PDF report</button><button class="atlas-tree-button" data-egypt-tool="offline">Offline map information</button></div><div class="atlas-nav-footer"><i></i> Egypt portfolio · Simulated facility data</div>`;
 $('#atlas-close-navigation').onclick=()=>setAtlasNavigation(false);
}
function setAtlasNavigation(open){$('#atlas-navigation').hidden=!open;$('#navigation-shade').hidden=!open;document.body.classList.toggle('navigation-open',open);$('#navigation-handle').setAttribute('aria-expanded',String(open));if(open){egyptReturnFocus=document.activeElement;$('#atlas-close-navigation').focus()}else egyptReturnFocus?.focus?.()}
const egyptOriginalRoute=route;
route=function(...args){if(args[0]==='overview'&&Array.isArray(egyptMapView?.center))egyptRenderedScope=null;egyptOriginalRoute(...args);setAtlasNavigation(false)};
$('#navigation-handle').onclick=()=>setAtlasNavigation($('#atlas-navigation').hidden);$('#navigation-shade').onclick=()=>setAtlasNavigation(false);
document.addEventListener('click',e=>{const target=e.target.closest('[data-egypt-region],[data-egypt-focus],[data-egypt-building],[data-egypt-tool],[data-egypt-action],[data-map-mode]');if(!target)return;const d=target.dataset;if(d.egyptRegion){state.region=d.egyptRegion;egyptMapView=null;route('overview',null,null);egyptFitToken++;if(state.region!=='all'&&egyptMap){const pts=scopedSites().map(s=>[s.lat,s.lon]);egyptMap.setMinZoom(5);egyptMap.fitBounds(pts.length>1?L.latLngBounds(pts):L.latLngBounds(pts).pad(.1),{maxZoom:10,padding:[70,70]})}else scheduleEgyptFit(false)}if(d.egyptFocus){const site=sites.find(s=>s.id===d.egyptFocus);state.region=site.region;egyptMapView={center:[site.lat,site.lon],zoom:12};route('overview',site.id,null)}if(d.egyptBuilding){state.region='all';state.tab='home';route('building',d.egyptSite,d.egyptBuilding)}if(d.mapMode){egyptMapMode=d.mapMode;render()}if(d.egyptAction==='fit')scheduleEgyptFit(true);if(d.egyptTool==='export'){exportReport();setAtlasNavigation(false)}if(d.egyptTool==='offline'){openDrawer(`<div class="eyebrow">EGYPT MAP</div><h2>Interactive geographic map</h2><p>This is a Leaflet map with real map coordinates, pan, wheel zoom, scale, campus markers, and geographic layers.</p><h3>Street map</h3><p>OpenStreetMap street tiles show detailed roads and place labels when connected to the internet. Public OSM tiles are not bulk downloaded.</p><h3>Offline map</h3><p>The local geographic basemap includes country and governorate boundaries, the Nile, cities, and downloaded road data. Select Offline map to use these files without network access. This overview basemap has less detail than online street tiles.</p><p>The map engine and geographic files are bundled in the project. Campus coordinates and telemetry are demonstration data.</p>`);setAtlasNavigation(false)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setAtlasNavigation(false);if(e.key==='Tab'&&!$('#atlas-navigation').hidden){const items=Array.from($('#atlas-navigation').querySelectorAll('button,summary,select:not(:disabled)'));if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
for(const [filename,assign] of [['egypt-roads.geojson',d=>{egyptRoadData=d}],['egypt-places.geojson',d=>{egyptPlaceData=d}]])fetch('assets/'+filename).then(r=>r.ok?r.json():Promise.reject()).then(d=>{assign(d);if(state.page==='overview')render()}).catch(()=>{});
render();

document.addEventListener('change',e=>{if(e.target.id==='nav-operation'&&['regions','facilities','alerts','work','insights','logs'].includes(e.target.value)){route(e.target.value);return}if(e.target.id==='nav-region'){state.region=e.target.value;egyptMapView=null;route('overview',null,null);setAtlasNavigation(true)}if(e.target.id==='nav-campus'){if(e.target.value){if(state.page==='overview')selectMapCampus(e.target.value);else{state.tab='home';route('campus',e.target.value,null)}}else route('overview',null,null);setAtlasNavigation(true)}if(e.target.id==='nav-building'&&e.target.value){changeContextBuilding(e.target.value)}});

function goToOverviewMap(){state.region='all';$('#navigation-handle').setAttribute('aria-label','Open navigation');egyptMapView=null;egyptRenderedScope=null;closeDrawer();route('overview',null,null)}
$('#overview-map-button').onclick=goToOverviewMap;
